test('timeout fails the task, aborts its worker, and ignores its late report', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.workDone('worker0'); // report in flight
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.equal((await h.taskTimeout(1)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: false });
  const abort = (await h.inFlight()).find((m) => m.action === 'Abort');
  assert.deepEqual([abort.from, abort.to, abort.data], ['run', 'worker1', {}]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: false });
});

