import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, more = {}) => ({ status, task0, task1, retried0: false, retried1: false, processed: 0, ...more });

test('initial state and queries', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('run'), null);
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.workDone('nobody', 1)).ok, false);
});

test('start sends Assign; both complete and items add up', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', { processed: 2 }));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 3 }));
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  const [f] = await h.inFlight();
  assert.deepEqual(f.data, { task: 1, outcome: 'failed', items: 0 });
  await h.deliver(f.id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', { retried1: true }));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0', 1); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', { retried1: true, processed: 1 }));
});

test('a retried task can complete', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
